  "RECOMMENDED": {"pt":"RECOMENDADO","it":"CONSIGLIATO","fr":"RECOMMANDÉ","no":"ANBEFALT","nl":"AANBEVOLEN","de":"EMPFOHLEN","sv":"REKOMMENDERAS","es":"RECOMENDADO","da":"ANBEFALET","fi":"SUOSITELTU","bg":"ПРЕПОРЪЧАНО","hr":"PREPORUČENO","sq":"REKOMANDOHET","mk":"ПРЕПОРАЧАНО","bs":"PREPORUČENO","ro":"RECOMANDAT","sl":"PRIPOROČENO","sr":"ПРЕПОРУЧЕНО","pl":"POLECANE","cs":"DOPORUČENO","tr":"ÖNERİLEN","uk":"РЕКОМЕНДУЄМО","kk":"ҰСЫНЫЛАДЫ","az":"TÖVSİYƏ OLUNUR","uz":"TAVSIYA ETILADI","fa":"پیشنهادی","ar":"موصى به","tg":"ТАВСИЯШУДА","vi":"ĐỀ XUẤT","zh":"推荐","ja":"おすすめ","ko":"추천"},
